function freshRuntime() {
  return { screen:'dashboard', test:null, title:'', questions:[], current:0, answers:{}, grades:{}, marked:{}, seen:{}, visits:{}, answerChanges:{}, timeByQuestion:{}, enteredAt:0, tracking:false, events:[], startedAt:0, deadlineAt:0, durationSeconds:0, modalOpen:false };
}
function migrateAttempts(items) { return Array.isArray(items) ? items.filter(Boolean).map((item) => ({ isTestRun:false, aiNotes:'', grades:{}, ...item })) : []; }
function sanitizeAIConfig(config={}) { const { apiKey, key, token, authorization, ...safe } = config || {}; if(safe.provider==='inception')safe.provider='openai';if(safe.authMode==='apiKey')safe.authMode=safe.provider==='openai'?'bearer':'header';return safe; }
function activeProfile(){return aiProfiles.find(profile=>profile.id===activeProfileId)||aiProfiles[0];}
function activateAIProfile(id,model=''){const profile=aiProfiles.find(item=>item.id===id);if(!profile)return;activeProfileId=profile.id;settings.activeAIProfileId=profile.id;storage.saveSettings(settings);aiConfig={...profile,model:model||profile.model||profile.models?.[0]||''};sessionApiKey=sessionKeys.get(profile.id)||'';}
function persistAIProfiles(){storage.saveAIProfiles(aiProfiles);storage.saveAIConfig(activeProfile());}
function escapeHTML(value) { return String(value ?? '').replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])); }
function uid(prefix='id') { return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`; }
function formatTime(seconds) { const safe=Math.max(0,Math.floor(Number(seconds)||0)); return `${String(Math.floor(safe/60)).padStart(2,'0')}:${String(safe%60).padStart(2,'0')}`; }
function wordCount(text) { return String(text||'').trim().split(/\s+/).filter(Boolean).length; }
function unique(values) { return [...new Set(values.filter(Boolean))]; }
function questionCatalog(){const map=new Map();const ensure=(subject)=>{if(!map.has(subject))map.set(subject,new Set());return map.get(subject);};(settings.customCatalog||[]).forEach(item=>{const set=ensure(item.subject);(item.chapters||[]).forEach(chapter=>set.add(chapter));});bank.forEach(question=>ensure(question.subject).add(question.topic||'Uncategorized'));return [...map.entries()].map(([subject,chapters])=>({subject,chapters:[...chapters].sort(),count:bank.filter(question=>question.subject===subject).length})).sort((a,b)=>a.subject.localeCompare(b.subject));}
function saveCatalog(catalog){settings.customCatalog=catalog.map(item=>({subject:item.subject,chapters:item.chapters}));storage.saveSettings(settings);}
function randomize(items, enabled=settings.shuffle) { return shuffleItems(items, enabled); }
function randomizeSets(items, enabled=settings.shuffle) { return shuffleQuestionSets(items, enabled); }
function saveCore() { storage.saveBank(bank); storage.saveAttempts(attempts); storage.saveTests(customTests); storage.saveSettings(settings); storage.saveAIConfig(aiConfig); storage.saveAIProfiles(aiProfiles); storage.saveTutor(tutorMessages); storage.saveTutorChats(tutorChats); storage.saveMistakeState(mistakeState); }
function downloadJSON(filename, value) { const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})); const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function warnStorageOnce(){if(storageWarningShown)return;storageWarningShown=true;showToast('Browser storage is unavailable or full. Export a backup before closing this page.','warn');}
function showToast(message, tone='') { const old=document.querySelector('#toast');old?.remove();const el=document.createElement('div');el.id='toast';el.className=`notice ${tone}`;el.style.cssText='position:fixed;right:18px;bottom:18px;z-index:60;max-width:420px;box-shadow:var(--shadow)';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),4000); }
function statusClass(status) { return status==='Correct'||status==='Graded'?'ok':status==='Wrong'?'bad':status==='Pending Review'?'pending':'skip'; }
function renderQuestionTable(table){if(!table)return'';const cols=Math.max((table.headers||[]).length,...((table.rows||[]).map(r=>r.length)),0);if(!cols)return'';return`<figure class="q-table">${table.caption?`<figcaption>${escapeHTML(table.caption)}</figcaption>`:''}<div class="table-wrap"><table class="data-table">${table.headers?.length?`<thead><tr>${table.headers.map(cell=>`<th>${escapeHTML(cell)}</th>`).join('')}</tr></thead>`:''}<tbody>${(table.rows||[]).map(row=>`<tr>${row.map(cell=>`<td>${escapeHTML(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></figure>`;}
function renderQuestionImage(image){if(!image)return'';return`<figure class="q-image"><img src="${escapeHTML(image.src)}" alt="${escapeHTML(image.alt||'Question diagram')}" loading="lazy">${image.caption?`<figcaption>${escapeHTML(image.caption)}</figcaption>`:''}</figure>`;}
function renderQuestionMedia(q,showSolutions=false){return`${q.passage?`<div class="passage"><b>Directions / Data:</b>\n${escapeHTML(q.passage)}</div>`:''}${showSolutions||!isAnswerRevealingMedia(q,q.table)?renderQuestionTable(q.table):''}${showSolutions||!isAnswerRevealingMedia(q,q.image)?renderQuestionImage(q.image):''}`;}

function uiIcon(name){const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tests:'M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4z M12 6v16',bank:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',tutor:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',ai:'M8 3v5 M16 3v5 M6 8h12v3a6 6 0 0 1-12 0z M12 17v4',history:'M4 18V9 M10 18V5 M16 18v-6 M3 21h18',mistakes:'M6 3h12v18l-6-4-6 4z M9 8h6 M9 11h4',guide:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',theme:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.tests}"/></svg>`;}
const NAV=[['dashboard','D','Dashboard'],['tests','P','Practice'],['bank','Q','Questions'],['tutor','AI','AI Tutor'],['ai','I','Import & AI'],['history','H','History'],['mistakes','!','Mistakes'],['guide','?','Guide'],['settings','S','Settings']];
function shell(title, body) {
  document.body.classList.toggle('dark',settings.theme==='dark');
  document.body.classList.toggle('tutor-view',view==='tutor');
  app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="side-brand"><div class="side-logo">PO</div><div>PREP STUDIO<small>Your study workspace</small></div></div><nav class="nav">${NAV.map(([id,icon,label])=>`<button class="nav-btn ${view===id?'active':''}" data-view="${id}" title="${label}" aria-label="${label}" ${view===id?'aria-current="page"':''}><span class="nav-icon">${uiIcon(id)}</span><span class="nav-label">${label}</span></button>`).join('')}</nav><div class="side-foot"><b><i></i> Private by default</b>Practice offline. Your progress stays in this browser. Back up regularly.</div></aside><section class="main-area"><header class="topbar"><div><small>Prep Studio / Study workspace</small><h1>${escapeHTML(title)}</h1></div><div class="top-actions"><button class="btn icon-button" data-action="theme-toggle" aria-label="Switch light or dark theme" title="Switch theme">${uiIcon('theme')}</button><button class="btn" data-view="guide">Help</button><button class="btn" data-action="quick-backup">Export backup</button><button class="btn primary" data-view="tests">Start a test</button></div></header><main class="content">${storage.hasPersistenceIssue()?'<div class="notice warn storage-warning"><b>Storage warning:</b> New changes are only in memory because browser storage is unavailable or full. Export a backup now and free browser storage before closing this page.</div>':''}${body}</main></section></div>`;
  bindShell();labelWorkspaceFields();
}
function labelWorkspaceFields(){document.querySelectorAll('.app-shell .field').forEach((field,index)=>{const label=field.querySelector('label');const input=field.querySelector('input,select,textarea');if(label&&input&&!label.contains(input)){input.id=input.id||`workspace-field-${index}`;label.htmlFor=input.id;}});}
function bindShell(){document.querySelector('[data-action="theme-toggle"]')?.addEventListener('click',()=>{settings.theme=settings.theme==='dark'?'light':'dark';storage.saveSettings(settings);document.body.classList.toggle('dark',settings.theme==='dark');});document.querySelectorAll('[data-view]').forEach((button)=>button.addEventListener('click',()=>navigate(button.dataset.view)));document.querySelector('[data-action="quick-backup"]')?.addEventListener('click',exportBackup);}
function navigate(next){pauseTracking('navigate-app');if(next==='tests')practiceSubject='';view=next;renderView();}
function renderView(){if(view==='dashboard')renderDashboard();else if(view==='tests')renderTests();else if(view==='bank')renderBank();else if(view==='tutor')renderTutor();else if(view==='ai')renderAIStudio();else if(view==='history')renderHistory();else if(view==='mistakes')renderMistakes();else if(view==='guide')renderGuide();else renderSettings();}

